import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

import '../assets/app_assets.dart';

/// Serves the dark variants of the hand-drawn icons in dark mode.
///
/// Every `Image.asset(AppIcons.x)` loads through `DefaultAssetBundle`, so
/// putting this bundle above the app swaps `assets/icons/...` for
/// `assets/icons_dark/...` (generated by `tool/make_dark_icons.dart`) without
/// touching any call site. Icons without a dark variant (white icons drawn over
/// photos) load unchanged. A new bundle per theme also gives the image cache
/// separate keys, so switching themes never shows a stale icon.
class ThemedAssetBundle extends CachingAssetBundle {
  ThemedAssetBundle({required this.dark, AssetBundle? parent})
    : _parent = parent ?? rootBundle;

  final bool dark;
  final AssetBundle _parent;

  static const _light = AppAssetDirs.icons;
  static const _dark = AppAssetDirs.iconsDark;

  /// Dark variants that exist, from the asset manifest (null until loaded).
  static Set<String>? _darkAssets;

  /// Reads the manifest once; call before the first frame.
  static Future<void> preload([AssetBundle? bundle]) async {
    if (_darkAssets != null) return;
    try {
      final manifest = await AssetManifest.loadFromAssetBundle(
        bundle ?? rootBundle,
      );
      _darkAssets = manifest
          .listAssets()
          .where((a) => a.startsWith(_dark))
          .toSet();
    } catch (_) {
      _darkAssets = const {};
    }
  }

  String _resolve(String key) {
    if (!dark || !key.startsWith(_light)) return key;
    final candidate = _dark + key.substring(_light.length);
    return (_darkAssets?.contains(candidate) ?? false) ? candidate : key;
  }

  @override
  Future<ByteData> load(String key) => _parent.load(_resolve(key));

  @override
  Future<ImmutableBuffer> loadBuffer(String key) =>
      _parent.loadBuffer(_resolve(key));

  @override
  Future<String> loadString(String key, {bool cache = true}) =>
      _parent.loadString(key, cache: cache);

  @override
  Future<T> loadStructuredData<T>(
    String key,
    Future<T> Function(String value) parser,
  ) => _parent.loadStructuredData(key, parser);
}

/// Puts the light or dark [ThemedAssetBundle] above [child].
class ThemedAssets extends StatefulWidget {
  const ThemedAssets({super.key, required this.dark, required this.child});

  final bool dark;
  final Widget child;

  @override
  State<ThemedAssets> createState() => _ThemedAssetsState();
}

class _ThemedAssetsState extends State<ThemedAssets> {
  final _light = ThemedAssetBundle(dark: false);
  final _darkBundle = ThemedAssetBundle(dark: true);

  @override
  Widget build(BuildContext context) => DefaultAssetBundle(
    bundle: widget.dark ? _darkBundle : _light,
    child: widget.child,
  );
}
